-- Thêm câu ví dụ thứ 2–3 cho các mẫu ngữ pháp Minna chỉ có 1 câu. Chạy lại an toàn (bỏ qua sortOrder đã có).
BEGIN;
INSERT INTO "Example" (jp, romaji, vi, "sortOrder", "grammarId")
SELECT t.jp, t.romaji, t.vi, t.so, t.gid
FROM (VALUES
 (7633, 1, 'それは 日本の お茶ですか、中国の お茶ですか。…日本の お茶です。', 'Sore wa Nihon no ocha desu ka, Chūgoku no ocha desu ka. … Nihon no ocha desu.', 'Đó là trà Nhật hay trà Trung Quốc? … Là trà Nhật.'),
 (7633, 2, 'あの 人は 先生ですか、学生ですか。…学生です。', 'Ano hito wa sensei desu ka, gakusei desu ka. … Gakusei desu.', 'Người kia là giáo viên hay học sinh? … Là học sinh.'),
 (7635, 1, 'あの 方は どなたですか。…IMCの 松本さんです。…そうですか。', 'Ano kata wa donata desu ka. … IMC no Matsumoto-san desu. … Sō desu ka.', 'Vị kia là ai vậy? … Là anh Matsumoto của công ty IMC. … Thế à.'),
 (7635, 2, 'この 時計は 日本のですか。…いいえ、スイスのです。…そうですか。', 'Kono tokei wa Nihon no desu ka. … Iie, Suisu no desu. … Sō desu ka.', 'Cái đồng hồ này là của Nhật à? … Không, của Thụy Sĩ. … Ra vậy.'),
 (7645, 1, 'わたしは 毎朝 パンと 卵を 食べます。', 'Watashi wa maiasa pan to tamago o tabemasu.', 'Sáng nào tôi cũng ăn bánh mì và trứng.'),
 (7645, 2, '教室に 机と いすが あります。', 'Kyōshitsu ni tsukue to isu ga arimasu.', 'Trong lớp học có bàn và ghế.'),
 (7646, 1, 'この ケーキ、おいしいですね。…ええ、そうですね。', 'Kono kēki, oishii desu ne. … Ē, sō desu ne.', 'Cái bánh này ngon nhỉ. … Ừ, đúng thế nhỉ.'),
 (7646, 2, 'きょうは 暑いですね。…ええ、本当に 暑いですね。', 'Kyō wa atsui desu ne. … Ē, hontō ni atsui desu ne.', 'Hôm nay nóng nhỉ. … Ừ, nóng thật nhỉ.'),
 (7648, 1, '日曜日 どこか 行きましたか。…いいえ、どこも 行きませんでした。', 'Nichiyōbi dokoka ikimashita ka. … Iie, doko mo ikimasen deshita.', 'Chủ nhật bạn có đi đâu không? … Không, tôi không đi đâu cả.'),
 (7648, 2, '冬休みは どこへも 行きません。うちに います。', 'Fuyuyasumi wa doko e mo ikimasen. Uchi ni imasu.', 'Kỳ nghỉ đông tôi không đi đâu cả. Tôi ở nhà.'),
 (7651, 1, 'いつ 国へ 帰りますか。…来月 帰ります。', 'Itsu kuni e kaerimasu ka. … Raigetsu kaerimasu.', 'Khi nào bạn về nước? … Tháng sau tôi về.'),
 (7651, 2, '誕生日は いつですか。…6月13日です。', 'Tanjōbi wa itsu desu ka. … Roku-gatsu jūsan-nichi desu.', 'Sinh nhật bạn là khi nào? … Ngày 13 tháng 6.'),
 (7652, 1, 'あしたは 休みですよ。', 'Ashita wa yasumi desu yo.', 'Ngày mai là ngày nghỉ đấy.'),
 (7652, 2, 'この 本、おもしろいですよ。どうぞ 読んで ください。', 'Kono hon, omoshiroi desu yo. Dōzo yonde kudasai.', 'Cuốn sách này hay lắm đấy. Mời bạn đọc.'),
 (7657, 1, 'あした いっしょに 昼ごはんを 食べませんか。…ええ、食べましょう。', 'Ashita issho ni hirugohan o tabemasen ka. … Ē, tabemashō.', 'Ngày mai cùng ăn trưa không? … Ừ, cùng ăn nhé.'),
 (7657, 2, 'ちょっと 休みませんか。…ええ、そう しましょう。', 'Chotto yasumimasen ka. … Ē, sō shimashō.', 'Nghỉ một chút không? … Ừ, làm vậy đi.'),
 (7660, 1, '「さようなら」は ベトナム語で 何ですか。…「Tạm biệt」です。', '"Sayōnara" wa Betonamu-go de nan desu ka. … "Tạm biệt" desu.', '"Sayounara" tiếng Việt là gì? … Là "Tạm biệt".'),
 (7660, 2, '「Book」は 日本語で 何ですか。…「本」です。', '"Book" wa Nihongo de nan desu ka. … "Hon" desu.', '"Book" tiếng Nhật là gì? … Là "hon".'),
 (7668, 1, 'この 部屋は 広いですが、ちょっと 暗いです。', 'Kono heya wa hiroi desu ga, chotto kurai desu.', 'Căn phòng này rộng nhưng hơi tối.'),
 (7668, 2, '日本語は おもしろいですが、難しいです。', 'Nihongo wa omoshiroi desu ga, muzukashii desu.', 'Tiếng Nhật thú vị nhưng khó.'),
 (7669, 1, 'あなたの かばんは どれですか。…あの 黒い かばんです。', 'Anata no kaban wa dore desu ka. … Ano kuroi kaban desu.', 'Cặp của bạn là cái nào? … Là cái cặp màu đen kia.'),
 (7669, 2, 'この 中で どれが いちばん 安いですか。…これです。', 'Kono naka de dore ga ichiban yasui desu ka. … Kore desu.', 'Trong số này cái nào rẻ nhất? … Cái này.'),
 (7672, 1, 'どんな 料理が 好きですか。…日本料理が 好きです。', 'Donna ryōri ga suki desu ka. … Nihon-ryōri ga suki desu.', 'Bạn thích món ăn nào? … Tôi thích món Nhật.'),
 (7672, 2, '奈良は どんな 町ですか。…古くて、静かな 町です。', 'Nara wa donna machi desu ka. … Furukute, shizuka na machi desu.', 'Nara là thành phố như thế nào? … Là một thành phố cổ kính và yên tĩnh.'),
 (7674, 1, 'きょうは 雨ですから、うちに います。', 'Kyō wa ame desu kara, uchi ni imasu.', 'Hôm nay trời mưa nên tôi ở nhà.'),
 (7674, 2, 'どうして 朝ごはんを 食べませんか。…時間が ありませんから。', 'Dōshite asagohan o tabemasen ka. … Jikan ga arimasen kara.', 'Tại sao bạn không ăn sáng? … Vì không có thời gian.'),
 (7688, 1, '肉と 魚と どちらが 好きですか。…魚の ほうが 好きです。', 'Niku to sakana to dochira ga suki desu ka. … Sakana no hō ga suki desu.', 'Thịt và cá, bạn thích cái nào hơn? … Tôi thích cá hơn.'),
 (7688, 2, '東京と 大阪と どちらが 大きいですか。…東京の ほうが 大きいです。', 'Tōkyō to Ōsaka to dochira ga ōkii desu ka. … Tōkyō no hō ga ōkii desu.', 'Tokyo và Osaka, nơi nào lớn hơn? … Tokyo lớn hơn.'),
 (7706, 1, '駅まで どうやって 行きますか。…歩いて 行きます。', 'Eki made dōyatte ikimasu ka. … Aruite ikimasu.', 'Bạn đến ga bằng cách nào? … Tôi đi bộ.'),
 (7706, 2, 'この 漢字は どうやって 読みますか。…「やま」と 読みます。', 'Kono kanji wa dōyatte yomimasu ka. … "Yama" to yomimasu.', 'Chữ kanji này đọc thế nào? … Đọc là "yama".'),
 (7707, 1, 'どの 傘が あなたのですか。…あの 赤い 傘です。', 'Dono kasa ga anata no desu ka. … Ano akai kasa desu.', 'Cái ô nào là của bạn? … Là cái ô màu đỏ kia.'),
 (7707, 2, 'どの バスに 乗りますか。…5番の バスに 乗ります。', 'Dono basu ni norimasu ka. … Go-ban no basu ni norimasu.', 'Bạn đi xe buýt nào? … Tôi đi xe buýt số 5.'),
 (7708, 1, '飲みます → 飲まない、起きます → 起きない、来ます → 来ない', 'Nomimasu → nomanai, okimasu → okinai, kimasu → konai', 'uống, thức dậy, đến (thể ない)'),
 (7708, 2, 'あした 会社へ 行かない。', 'Ashita kaisha e ikanai.', 'Ngày mai tôi không đi làm.'),
 (7714, 1, '飲みます → 飲む、寝ます → 寝る、します → する', 'Nomimasu → nomu, nemasu → neru, shimasu → suru', 'uống, ngủ, làm (thể từ điển)'),
 (7714, 2, 'わたしの 趣味は 写真を 撮る ことです。', 'Watashi no shumi wa shashin o toru koto desu.', 'Sở thích của tôi là chụp ảnh.'),
 (7718, 1, '日本語が なかなか 上手に なりません。', 'Nihongo ga nakanaka jōzu ni narimasen.', 'Tiếng Nhật của tôi mãi mà không giỏi lên được.'),
 (7718, 2, 'バスが なかなか 来ません。', 'Basu ga nakanaka kimasen.', 'Xe buýt mãi mà chưa tới.'),
 (7720, 1, '買って → 買った、待って → 待った、して → した', 'Katte → katta, matte → matta, shite → shita', 'mua, đợi, làm (thể た)'),
 (7720, 2, 'きのう 友達と 映画を 見た。', 'Kinō tomodachi to eiga o mita.', 'Hôm qua tôi đã xem phim với bạn.'),
 (7726, 1, 'この 部屋、狭いけど、駅から 近いよ。', 'Kono heya, semai kedo, eki kara chikai yo.', 'Phòng này chật nhưng gần ga đấy.'),
 (7726, 2, '日本語は 難しいけど、おもしろい。', 'Nihongo wa muzukashii kedo, omoshiroi.', 'Tiếng Nhật khó nhưng thú vị.'),
 (7728, 1, '日本の 食べ物に ついて どう 思いますか。…おいしいと 思います。', 'Nihon no tabemono ni tsuite dō omoimasu ka. … Oishii to omoimasu.', 'Bạn nghĩ thế nào về đồ ăn Nhật? … Tôi nghĩ là ngon.'),
 (7728, 2, 'この 映画に ついて どう 思いますか。…ちょっと 長いと 思います。', 'Kono eiga ni tsuite dō omoimasu ka. … Chotto nagai to omoimasu.', 'Bạn nghĩ thế nào về bộ phim này? … Tôi nghĩ là hơi dài.'),
 (7731, 1, 'あした 学校で 運動会が あります。', 'Ashita gakkō de undōkai ga arimasu.', 'Ngày mai ở trường có hội thao.'),
 (7731, 2, '来週 京都で お祭りが あります。', 'Raishū Kyōto de omatsuri ga arimasu.', 'Tuần sau ở Kyoto có lễ hội.'),
 (7758, 1, 'きのうは 熱が ありました。それで 会社を 休みました。', 'Kinō wa netsu ga arimashita. Sorede kaisha o yasumimashita.', 'Hôm qua tôi bị sốt. Vì vậy tôi đã nghỉ làm.'),
 (7758, 2, '駅から 近いし、安いんです。…それで この アパートに したんですね。', 'Eki kara chikaishi, yasuin desu. … Sorede kono apāto ni shitan desu ne.', 'Vừa gần ga lại vừa rẻ. … Vì vậy mà bạn chọn căn hộ này nhỉ.'),
 (7762, 1, 'はさみは どこですか。…引き出しに 入れて あります。', 'Hasami wa doko desu ka. … Hikidashi ni irete arimasu.', 'Cái kéo ở đâu? … Được để trong ngăn kéo.'),
 (7762, 2, '地図は 壁に はって あります。', 'Chizu wa kabe ni hatte arimasu.', 'Bản đồ được dán trên tường.'),
 (7782, 1, '傘を 持たないで、出かけました。', 'Kasa o motanaide, dekakemashita.', 'Tôi đã ra ngoài mà không mang ô.'),
 (7782, 2, 'バスに 乗らないで、歩いて 帰りました。', 'Basu ni noranaide, aruite kaerimashita.', 'Tôi không đi xe buýt mà đi bộ về.'),
 (7784, 1, 'パソコンを 買いたいんですが……。…パソコンなら、駅の 前の 店が 安いですよ。', 'Pasokon o kaitain desu ga…… . … Pasokon nara, eki no mae no mise ga yasui desu yo.', 'Tôi muốn mua máy tính… … Máy tính thì cửa hàng trước ga rẻ đấy.'),
 (7784, 2, '日本語なら、山田先生に 聞いて ください。', 'Nihongo nara, Yamada-sensei ni kiite kudasai.', 'Nếu là tiếng Nhật thì hãy hỏi thầy Yamada.'),
 (7798, 1, 'あしたの 会議が 中止に なったのを 知って いますか。…いいえ、知りませんでした。', 'Ashita no kaigi ga chūshi ni natta no o shitte imasu ka. … Iie, shirimasen deshita.', 'Bạn có biết cuộc họp ngày mai bị hủy không? … Không, tôi không biết.'),
 (7798, 2, '田中さんが 入院したのを 知って いますか。', 'Tanaka-san ga nyūin shita no o shitte imasu ka.', 'Bạn có biết anh Tanaka nhập viện không?'),
 (7808, 1, 'わたしは 先生に 作文を 見て いただきました。', 'Watashi wa sensei ni sakubun o mite itadakimashita.', 'Tôi được thầy xem giúp bài văn.'),
 (7808, 2, 'わたしは 部長に 駅まで 送って いただきました。', 'Watashi wa buchō ni eki made okutte itadakimashita.', 'Tôi được trưởng phòng đưa đến ga.'),
 (7809, 1, '先生が 本を 貸して くださいました。', 'Sensei ga hon o kashite kudasaimashita.', 'Thầy đã cho tôi mượn sách.'),
 (7809, 2, '社長が 駅まで 送って くださいました。', 'Shachō ga eki made okutte kudasaimashita.', 'Giám đốc đã đưa tôi đến ga.'),
 (7811, 1, 'すみませんが、もう 少し ゆっくり 話して くださいませんか。', 'Sumimasen ga, mō sukoshi yukkuri hanashite kudasaimasen ka.', 'Xin lỗi, anh có thể nói chậm hơn một chút được không ạ?'),
 (7811, 2, 'この 漢字の 読み方を 教えて くださいませんか。', 'Kono kanji no yomikata o oshiete kudasaimasen ka.', 'Anh có thể chỉ giúp tôi cách đọc chữ kanji này được không ạ?')
) AS t(gid, so, jp, romaji, vi)
WHERE NOT EXISTS (SELECT 1 FROM "Example" e WHERE e."grammarId" = t.gid AND e."sortOrder" = t.so);
COMMIT;
